  Theorem open_B :
    exists fxE RE ME,
      msteps RSEGS (st fx R 0x64568 M) (st fxE RE 0x126588 ME)
      (* [comment removed for export] *)
      /\ getr RE (reg 17) = Z_to_bv 64 66 /\ getr RE (reg 10) = Z_to_bv 64 2 /\ getr RE (reg 11) = Z_to_bv 64 (S - 1128) /\ getr RE (reg 12) = Z_to_bv 64 2
      /\ getr RE (reg 9) = Z_to_bv 64 1319120 /\ getr RE (reg 18) = Z_to_bv 64 2 /\ getr RE (reg 19) = Z_to_bv 64 (S - 1128) /\ getr RE (reg 22) = Z_to_bv 64 (n + 18)
      /\ L5.u64_at RSEGS ME (S - 1128) (S - 464) /\ L5.u64_at RSEGS ME (S - 1120) (n + 17) /\ L5.u64_at RSEGS ME (S - 1112) 127620 /\ L5.u64_at RSEGS ME (S - 1104) 1
      /\ rdn RSEGS ME (Z_to_bv 64 (S - 464)) (17 + length bs) = Some (PRE17 ++ bs) /\ rdn RSEGS ME (Z_to_bv 64 127620) 1 = Some SUF1
      /\ L5.u32_at RSEGS ME 1319240 2
      /\ agree0 M ME S /\ mem_grows M ME
      /\ (forall fx' RX MX,
            (forall x : word, ~ (S - 1128 <= bv_unsigned x < S - 1096) -> MX x = ME x) -> mem_grows ME MX ->
            (forall k, In k [2; 3; 4; 8; 9; 21; 23; 24; 25; 26; 27]%nat -> getr RX (reg k) = getr RE (reg k)) ->
            exists fxE2 RE2 ME2,
              msteps RSEGS (st fx' RX 0x126594 MX) (st fxE2 RE2 0x126588 ME2)
              (* [comment removed for export] *)
              /\ getr RE2 (reg 17) = Z_to_bv 64 66 /\ getr RE2 (reg 10) = Z_to_bv 64 2 /\ getr RE2 (reg 11) = Z_to_bv 64 (S - 568) /\ getr RE2 (reg 12) = Z_to_bv 64 1
              /\ getr RE2 (reg 9) = Z_to_bv 64 1319120 /\ getr RE2 (reg 18) = Z_to_bv 64 1 /\ getr RE2 (reg 19) = Z_to_bv 64 (S - 568) /\ getr RE2 (reg 22) = Z_to_bv 64 0
              /\ L5.u64_at RSEGS ME2 (S - 568) 0 /\ L5.u64_at RSEGS ME2 (S - 560) 0
              /\ L5.u32_at RSEGS ME2 1319240 2
              /\ agree0 M ME2 S /\ mem_grows M ME2
              /\ (forall fx'' RY MY,
                    (forall x : word, ~ (S - 584 <= bv_unsigned x < S - 552) -> MY x = ME2 x) -> mem_grows ME2 MY ->
                    (forall k, In k [2; 3; 4; 8; 9; 21; 23; 24; 25; 26; 27]%nat -> getr RY (reg k) = getr RE2 (reg k)) ->
                    exists fxF RF MF,
                      msteps RSEGS (st fx'' RY 0x126594 MY) (st fxF RF 0x11eba4 MF)
                      /\ getr RF (reg 10) = Z_to_bv 64 2 /\ getr RF (reg 2) = Z_to_bv 64 S
                      /\ agree0 M MF S /\ mem_grows M MF
                      /\ L5.u32_at RSEGS MF 1319120 5 /\ L5.u64_at RSEGS MF 1319216 0 /\ L5.u64_at RSEGS MF 1319208 6924696
                      /\ L5.u64_at RSEGS MF 1319176 0 /\ L5.u64_at RSEGS MF 1319160 0 /\ L5.u64_at RSEGS MF 1319152 0 /\ L5.u64_at RSEGS MF 1319128 0 /\ L5.u64_at RSEGS MF 1319136 0 /\ getr RF (reg 4) = getr R (reg 4))).
